import { MakeLogicType, connect, kea, path, selectors } from 'kea'

import { FEATURE_FLAGS, OrganizationMembershipLevel } from 'lib/constants'
import { FeatureFlagsSet, featureFlagLogic } from 'lib/logic/featureFlagLogic'
import { organizationLogic } from 'scenes/organizationLogic'

import { OrganizationType } from '~/types'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface tagManagementAccessLogicValues {
    featureFlags: FeatureFlagsSet // featureFlagLogic
    currentOrganization: OrganizationType | null // organizationLogic
    canManageTags: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface tagManagementAccessLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        canManageTags: (featureFlags: FeatureFlagsSet, currentOrganization: OrganizationType | null) => boolean
    }
}

export type tagManagementAccessLogicType = MakeLogicType<
    tagManagementAccessLogicValues,
    {},
    Record<string, any>,
    tagManagementAccessLogicMeta
>

export const tagManagementAccessLogic = kea<tagManagementAccessLogicType>([
    path(['lib', 'logic', 'tagManagementAccessLogic']),
    connect(() => ({
        values: [featureFlagLogic, ['featureFlags'], organizationLogic, ['currentOrganization']],
    })),
    selectors({
        canManageTags: [
            (s) => [s.featureFlags, s.currentOrganization],
            (flags: FeatureFlagsSet, organization: OrganizationType | null): boolean =>
                !!flags[FEATURE_FLAGS.TAG_MANAGEMENT] &&
                (organization?.membership_level ?? 0) >= OrganizationMembershipLevel.Admin,
        ],
    }),
])
